## 文件 1: `D:/Ainos/kernel/ai-scheduler.h`

此文件定义调度器内部数据结构，包括任务描述符、优先级队列、调度器全局状态以及导出的API。

```c
/*
 * ai-scheduler.h - Ainos OS AI Scheduler Internal Header
 *
 * Defines internal data structures for AI task scheduling,
 * including multi-level priority queues, CFS-like vruntime,
 * and resource management for GPU/NPU.
 */

#ifndef _AI_SCHEDULER_H
#define _AI_SCHEDULER_H

#include <linux/types.h>
#include <linux/rbtree.h>
#include <linux/list.h>
#include <linux/mutex.h>
#include <linux/completion.h>
#include <linux/timer.h>
#include <linux/kthread.h>
#include <linux/sched.h>
#include <linux/cpumask.h>
#include <ainos/ai-abi.h>   /* Public ABI structures */

/* Priority levels: 0 (highest) to 4 (lowest) */
#define AI_PRIO_LEVELS 5

/* Task states */
enum ai_task_state {
    AI_TASK_READY,
    AI_TASK_RUNNING,
    AI_TASK_WAITING_DEVICE,
    AI_TASK_COMPLETED,
    AI_TASK_FAILED,
};

/* Resource types */
enum ai_resource_type {
    AI_RESOURCE_CPU,
    AI_RESOURCE_GPU,
    AI_RESOURCE_NPU,
};

/* Forward declaration */
struct ai_scheduler;

/**
 * struct ai_task - AI task descriptor
 * @node:         Red-black tree node for queue insertion
 * @id:           Unique task ID
 * @priority:     0 (highest) .. 4 (lowest)
 * @vruntime:     Virtual runtime for CFS-like fairness
 * @exec_time_ns: Expected execution time (for watchdog)
 * @start_time:   Task start timestamp
 * @state:        Current task state
 * @resource:     Which accelerator is needed
 * @dev_id:       Specific device index (0..n)
 * @func:         Kernel function to execute
 * @data:         Private data for the function
 * @result_code:  Return code of task
 * @completion:   Signalled when task finishes/fails
 * @timeout:      Timer for watchdog
 * @owner:        Pointer to owning scheduler
 * @wq_entry:     For waitqueue when pending on resource
 */
struct ai_task {
    struct rb_node         node;
    u64                    id;
    int                    priority;        /* 0..4 */
    u64                    vruntime;
    u64                    exec_time_ns;    /* expected */
    ktime_t                start_time;
    enum ai_task_state     state;
    enum ai_resource_type  resource;
    int                    dev_id;
    int (*func)(void *data);
    void                  *data;
    int                    result_code;
    struct completion      completion;
    struct timer_list      timeout;
    struct ai_scheduler   *owner;
    struct list_head       wq_entry;
};

/**
 * struct ai_prio_queue - Priority level queue
 * @tree:      Red-black tree of runnable tasks sorted by vruntime
 * @nr:        Number of tasks in this queue
 * @lock:      Protects tree and nr
 */
struct ai_prio_queue {
    struct rb_root  tree;
    unsigned int    nr;
    spinlock_t      lock;   /* use spinlock for fast path inside irq? */
};

/**
 * struct ai_device - Represents a GPU/NPU device
 * @busy:       True if currently in use
 * @task:       The task occupying the device (NULL if free)
 * @lock:       Protects busy and task
 */
struct ai_device {
    bool                busy;
    struct ai_task     *task;
    spinlock_t          lock;
};

/**
 * struct ai_scheduler - Global AI scheduler state
 * @queues:          Priority queues, index 0 is highest
 * @queue_mask:      Bitmask of non-empty queues for fast lookup
 * @worker_thread:   Kernel thread executing CPU tasks
 * @nr_cpu_devices:  Number of CPU worker threads (one per core?)
 * @gpu_devices:     Array of GPU devices
 * @gpu_count:       Number of GPUs registered
 * @npu_devices:     Array of NPU devices
 * @npu_count:       Number of NPUs registered
 * @watchdog_timer:  Periodic watchdog timer
 * @lock:            Global scheduler mutex
 * @next_task_id:    Monotonically increasing task ID
 */
struct ai_scheduler {
    struct ai_prio_queue    queues[AI_PRIO_LEVELS];
    unsigned long           queue_mask;     /* bit i set if queue[i] not empty */
    struct task_struct     *worker_thread;
    int                     nr_cpu_devices;
    struct ai_device       *gpu_devices;
    int                     gpu_count;
    struct ai_device       *npu_devices;
    int                     npu_count;
    struct timer_list       watchdog_timer;
    struct mutex            lock;
    atomic64_t              next_task_id;
    bool                    initialized;
};

/* --- Kernel API exported to other modules --- */

/* Initialize the scheduler (called by module init) */
int ai_scheduler_init(struct ai_scheduler *sched, int cpu_workers,
                      int gpu_count, int npu_count);

/* Shutdown scheduler, cancel all tasks */
void ai_scheduler_shutdown(struct ai_scheduler *sched);

/* Submit a new AI task; returns task id or negative error */
int ai_scheduler_submit(struct ai_scheduler *sched, int priority,
                        enum ai_resource_type resource, int dev_id,
                        int (*func)(void *data), void *data,
                        u64 exec_time_ns);

/* Wait for completion of a task (blocking) */
int ai_scheduler_wait(struct ai_scheduler *sched, int task_id);

/* Cancel a task if it hasn't started yet */
int ai_scheduler_cancel(struct ai_scheduler *sched, int task_id);

/* For internal use: enqueue a task into the scheduler */
void ai_scheduler_enqueue(struct ai_scheduler *sched, struct ai_task *task);

/* Get current global scheduler (singleton) */
struct ai_scheduler *ai_scheduler_get(void);

/* Hook called from worker when a task finishes */
void ai_task_complete(struct ai_task *task, int result);

#endif /* _AI_SCHEDULER_H */
