## 文件 2: `D:/Ainos/kernel/ai-scheduler-policy.c`

此文件实现调度策略：基于 CFS 的公平调度（vruntime）、5 级优先级抢占、负载均衡以及相关的队列操作。

```c
/*
 * ai-scheduler-policy.c - AI Scheduler Policy Implementation
 *
 * Implements a hybrid scheduling policy:
 *   - 5 static priority levels (0..4)
 *   - Within each level, tasks are ordered by vruntime (CFS-like)
 *   - When a higher-priority task becomes ready, it preempts lower ones
 *   - Load balancing: distribute CPU tasks over worker threads,
 *     assign GPU/NPU tasks to the least loaded device of that type.
 *
 * The core operations: enqueue, dequeue, pick_next, and requeue are
 * provided for the scheduler main loop.
 */

#include "ai-scheduler.h"
#include <linux/slab.h>
#include <linux/hardirq.h>

/* Compare two tasks by vruntime for red-black tree ordering */
static inline int task_less_than(struct ai_task *a, struct ai_task *b)
{
    if (a->vruntime < b->vruntime)
        return 1;
    if (a->vruntime > b->vruntime)
        return 0;
    /* Break ties by ID for stability */
    return a->id < b->id;
}

/* Insert task into the given priority queue's red-black tree */
static void __enqueue_task(struct ai_prio_queue *queue, struct ai_task *task)
{
    struct rb_node **new = &(queue->tree.rb_node), *parent = NULL;
    struct ai_task *this;

    while (*new) {
        this = container_of(*new, struct ai_task, node);
        parent = *new;
        if (task_less_than(task, this))
            new = &((*new)->rb_left);
        else
            new = &((*new)->rb_right);
    }

    rb_link_node(&task->node, parent, new);
    rb_insert_color(&task->node, &queue->tree);
    queue->nr++;
}

/* Remove the leftmost (lowest vruntime) task from the queue */
static struct ai_task *__dequeue_first(struct ai_prio_queue *queue)
{
    struct rb_node *leftmost;

    leftmost = rb_first(&queue->tree);
    if (!leftmost)
        return NULL;

    struct ai_task *task = container_of(leftmost, struct ai_task, node);
    rb_erase(leftmost, &queue->tree);
    queue->nr--;
    return task;
}

/* Remove a specific task from the queue */
static void __dequeue_task(struct ai_prio_queue *queue, struct ai_task *task)
{
    rb_erase(&task->node, &queue->tree);
    queue->nr--;
}

/**
 * ai_scheduler_enqueue - Add a task to the appropriate priority queue
 * @sched: the global scheduler
 * @task:  task to enqueue
 *
 * Must be called with sched->lock held.
 */
void ai_scheduler_enqueue(struct ai_scheduler *sched, struct ai_task *task)
{
    struct ai_prio_queue *queue;
    unsigned long flags;

    if (task->priority < 0 || task->priority >= AI_PRIO_LEVELS) {
        pr_err("ai_scheduler: invalid priority %d\n", task->priority);
        return;
    }

    queue = &sched->queues[task->priority];
    spin_lock_irqsave(&queue->lock, flags);
    __enqueue_task(queue, task);
    set_bit(task->priority, &sched->queue_mask);
    spin_unlock_irqrestore(&queue->lock, flags);
    task->state = AI_TASK_READY;
}

/**
 * pick_next_task - Select the highest priority runnable task
 * @sched: the scheduler
 *
 * Returns the task with the lowest vruntime in the highest non-empty priority
 * queue, or NULL if no tasks are ready. The caller is responsible for removing
 * it from the queue.
 */
static struct ai_task *pick_next_task(struct ai_scheduler *sched)
{
    int prio;
    unsigned long flags;
    struct ai_prio_queue *queue;
    struct ai_task *task = NULL;

    /* Find highest priority non-empty queue */
    prio = find_first_bit(&sched->queue_mask, AI_PRIO_LEVELS);
    if (prio >= AI_PRIO_LEVELS)
        return NULL;

    queue = &sched->queues[prio];
    spin_lock_irqsave(&queue->lock, flags);
    task = __dequeue_first(queue);
    if (queue->nr == 0)
        clear_bit(prio, &sched->queue_mask);
    spin_unlock_irqrestore(&queue->lock, flags);

    return task;
}

/**
 * update_vruntime - Increase vruntime based on actual execution time
 * @task:    the task
 * @delta_ns: nanoseconds the task has run
 *
 * For CFS-like fairness, tasks with higher priority get a smaller weight,
 * causing their vruntime to advance more slowly. The base weight formula:
 *   weight = 1024 / (prio + 1)   (prio 0 -> weight 1024, prio 4 -> weight 204)
 * Then increment vruntime += delta_ns * (NICE_0_LOAD / weight)
 * Here NICE_0_LOAD = 1024.
 */
static void update_vruntime(struct ai_task *task, u64 delta_ns)
{
    u32 weight;

    /* Map priority 0..4 to weights 1024, 512, 341, 256, 204 */
    weight = 1024 / (task->priority + 1);
    if (weight == 0)
        weight = 1;

    /* Multiply by 1024 to avoid fraction, then divide by weight */
    task->vruntime += div64_u64(delta_ns * 1024, weight);
}

